//! Smoke test for `generate_v1` (cell E1). Constructs a minimal IR
//! `Module` by hand (one feature, no kinds), runs the emitter, and
//! verifies the structural invariants the proposal locks in:
//!
//! 1. At least one feature `.gen.go` plus the root `go.mod`.
//! 2. `go.mod` carries the resolved module path and the
//!    `require lazuli.dev/runtime/lazuli <version>` line.
//! 3. Each `.gen.go` opens with the Code Connect-style banner
//!    (`// Code generated by lazuli; DO NOT EDIT.`) and a
//!    matching `package <feature_name>` directive.
//!
//! Hand-rolled IR (not via the analyzer) keeps the test
//! deliberately decoupled from grammar-side drift.

use lazuli_codegen_go::{GoEmitOptions, LAZULI_GO_VERSION, generate_v1};
use lazuli_ir::{
    AppManifest, Assignment, BuiltinType, Command, CommandEffect, CommandInput, CommandKind,
    CreateEffect, Defaults, EnumDecl, EnumVariant, Expr, Feature, Field, Module, Path, Policies,
    PolicyRef, QualifiedName, Resource, StorageValue, TypeRef, TypedSlot,
};

fn empty_feature(name: &str) -> Feature {
    Feature {
        name: name.to_owned(),
        purpose: None,
        non_goals: Vec::new(),
        context_path: None,
        defaults: Defaults {
            tenancy: None,
            timestamps: false,
            policy: None,
        },
        uses: Vec::new(),
        requirements: Vec::new(),
        enums: Vec::new(),
        resources: Vec::new(),
        events: Vec::new(),
        rules: Vec::new(),
        policies: Policies {
            categories: Vec::new(),
            fields: Vec::new(),
            span_ref: None,
        },
        commands: Vec::new(),
        apis: Vec::new(),
        records: Vec::new(),
        queries: Vec::new(),
        workflows: Vec::new(),
        jobs: Vec::new(),
        webhooks: Vec::new(),
        notifications: Vec::new(),
        event_groups: Vec::new(),
        tenant_migrations: Vec::new(),
        translation: None,
        auth: None,
        surfaces: Vec::new(),
        extensions: Vec::new(),
        escape_routes: Vec::new(),
        agents: Vec::new(),
        previous_names: Vec::new(),
        span_ref: None,
    }
}

fn minimal_app_manifest(name: &str) -> AppManifest {
    // `AppManifest` has no `Default` impl (the bucket-observability
    // cycle dropped `Eq` derive so `f64` sample-rate fields can
    // coexist). Build the whole shape explicitly.
    AppManifest {
        name: name.to_owned(),
        title: None,
        version: None,
        targets: Vec::new(),
        default_locale: None,
        default_timezone: None,
        auth_failed_redirect: None,
        not_found: None,
        uses: Vec::new(),
        packs: Vec::new(),
        bindings: Vec::new(),
        architecture: None,
        services: Vec::new(),
        communication: None,
        environments: Vec::new(),
        urls: Vec::new(),
        cors: None,
        env: Vec::new(),
        integrations: Vec::new(),
        capabilities: Vec::new(),
        runtime: Vec::new(),
        deploy: None,
        logging: None,
        tracing: None,
        locale: None,
        span_ref: None,
    }
}

fn minimal_module(app_name: &str, feature_name: &str) -> Module {
    Module {
        workspace: None,
        contracts: Vec::new(),
        app: Some(minimal_app_manifest(app_name)),
        registry: None,
        profiles: Vec::new(),
        features: vec![empty_feature(feature_name)],
    }
}

#[test]
fn emits_go_mod_and_feature_stub() {
    let module = minimal_module("test_app", "customer");
    let files = generate_v1(&module, &GoEmitOptions::default());

    // Invariant 1: at least go.mod + one feature stub.
    assert!(
        files.len() >= 2,
        "expected go.mod plus at least one feature stub, got {} files",
        files.len()
    );

    let go_mod = files
        .iter()
        .find(|f| f.path == "go.mod")
        .expect("go.mod missing from emitter output");
    let feature_file = files
        .iter()
        .find(|f| f.path == "customer/customer.gen.go")
        .expect("customer feature stub missing");

    // Invariant 2: go.mod resolves the derived module path and the
    // crate-pinned Lazuli Go version.
    assert!(
        go_mod.contents.contains("module lazuli/test-app"),
        "expected `module lazuli/test-app` in go.mod, got:\n{}",
        go_mod.contents
    );
    assert!(
        go_mod
            .contents
            .contains(&format!("lazuli.dev/runtime {}", LAZULI_GO_VERSION)),
        "expected `lazuli.dev/runtime {LAZULI_GO_VERSION}` in go.mod, got:\n{}",
        go_mod.contents
    );

    // Invariant 3: each .gen.go opens with the banner + the feature
    // package directive.
    assert!(
        feature_file
            .contents
            .contains("// Code generated by lazuli; DO NOT EDIT."),
        "missing Code Connect-style banner in feature stub:\n{}",
        feature_file.contents
    );
    assert!(
        feature_file.contents.contains("\npackage customer\n"),
        "expected `package customer` in feature stub:\n{}",
        feature_file.contents
    );
}

#[test]
fn module_name_override_wins_over_app_name() {
    let module = minimal_module("test_app", "customer");
    let options = GoEmitOptions {
        module_name: Some("github.com/acme/custom-name".to_owned()),
        lazuli_go_version: LAZULI_GO_VERSION.to_owned(),
        check: false,
    };
    let files = generate_v1(&module, &options);
    let go_mod = files
        .iter()
        .find(|f| f.path == "go.mod")
        .expect("go.mod missing");
    assert!(go_mod.contents.contains("module github.com/acme/custom-name"));
}

#[test]
fn deterministic_output_across_runs() {
    let module = minimal_module("hostpoint", "customer");
    let a = generate_v1(&module, &GoEmitOptions::default());
    let b = generate_v1(&module, &GoEmitOptions::default());
    assert_eq!(a.len(), b.len());
    for (left, right) in a.iter().zip(b.iter()) {
        assert_eq!(left.path, right.path);
        assert_eq!(left.contents, right.contents);
    }
}

#[test]
fn resource_kind_emits_typed_struct_and_resource_value() {
    // Cell E2 integration smoke: a feature carrying one resource
    // surfaces an extra `<feature>/resource.gen.go` alongside the
    // stub. Typed struct + `lazuli.Resource[T]` value land per
    // proposal §3.1.
    let mut module = minimal_module("hostpoint", "customer");
    let resource = Resource {
        name: "customer".to_owned(),
        tenancy: None,
        soft_delete: false,
        timestamps: None,
        fields: vec![Field {
            name: "name".to_owned(),
            type_ref: TypeRef::Builtin(BuiltinType::Text),
            required: true,
            unique: false,
            default: None,
            derived_from: None,
            previous_names: Vec::new(),
            span_ref: None,
        }],
        constraints: Vec::new(),
        validate: None,
        validates: Vec::new(),
        retention: None,
        previous_names: Vec::new(),
        span_ref: None,
    };
    module.features[0].resources.push(resource);

    let files = generate_v1(&module, &GoEmitOptions::default());
    let resource_file = files
        .iter()
        .find(|f| f.path == "customer/resource.gen.go")
        .expect("expected customer/resource.gen.go alongside the stub");
    assert!(
        resource_file.contents.contains("type Customer struct"),
        "expected struct declaration in resource.gen.go:\n{}",
        resource_file.contents
    );
    assert!(
        resource_file
            .contents
            .contains("var customerResource = lazuli.Resource[Customer]"),
        "expected `var customerResource = lazuli.Resource[Customer]` in resource.gen.go:\n{}",
        resource_file.contents
    );
}

#[test]
fn resource_kind_skips_file_when_feature_declares_no_resources_or_records() {
    // A bare feature stays at the `<feature>.gen.go` stub only; we
    // don't materialise an empty `resource.gen.go` because a single
    // `package <feature>` line provides no signal and would clutter
    // the listing.
    let module = minimal_module("hostpoint", "customer");
    let files = generate_v1(&module, &GoEmitOptions::default());
    assert!(
        files
            .iter()
            .all(|f| f.path != "customer/resource.gen.go"),
        "expected no resource.gen.go for an empty feature, got files: {:?}",
        files.iter().map(|f| &f.path).collect::<Vec<_>>()
    );
}

#[test]
fn enum_kind_emits_typed_alias_and_const_block() {
    // Cell E2.5 integration smoke: a feature carrying one int-typed
    // enum surfaces an extra `<feature>/enum.gen.go` alongside the
    // stub. Typed alias + aligned const block land per proposal §3.
    let mut module = minimal_module("hostpoint", "customer");
    module.features[0].enums.push(EnumDecl {
        name: "CustomerStatus".to_owned(),
        variants: vec![
            EnumVariant {
                name: "lead".to_owned(),
                storage_value: Some(StorageValue::Integer(10)),
                previous_names: Vec::new(),
            },
            EnumVariant {
                name: "active".to_owned(),
                storage_value: Some(StorageValue::Integer(20)),
                previous_names: Vec::new(),
            },
        ],
        previous_names: Vec::new(),
        span_ref: None,
    });

    let files = generate_v1(&module, &GoEmitOptions::default());
    let enum_file = files
        .iter()
        .find(|f| f.path == "customer/enum.gen.go")
        .expect("expected customer/enum.gen.go alongside the stub");
    assert!(
        enum_file.contents.contains("type CustomerStatus int64"),
        "expected typed alias in enum.gen.go:\n{}",
        enum_file.contents
    );
    assert!(
        enum_file.contents.contains("const ("),
        "expected const block in enum.gen.go:\n{}",
        enum_file.contents
    );
    assert!(
        enum_file
            .contents
            .contains("CustomerStatusLead   CustomerStatus = 10"),
        "expected aligned const row in enum.gen.go:\n{}",
        enum_file.contents
    );
}

#[test]
fn enum_kind_skips_file_when_feature_declares_no_enums() {
    // A bare feature should not materialise `enum.gen.go`. Mirrors
    // the resource-side skip rule so the output listing stays
    // signal-rich.
    let module = minimal_module("hostpoint", "customer");
    let files = generate_v1(&module, &GoEmitOptions::default());
    assert!(
        files.iter().all(|f| f.path != "customer/enum.gen.go"),
        "expected no enum.gen.go for an empty feature, got files: {:?}",
        files.iter().map(|f| &f.path).collect::<Vec<_>>()
    );
}

#[test]
fn lazuli_go_version_override_lands_in_go_mod() {
    let module = minimal_module("hostpoint", "customer");
    let options = GoEmitOptions {
        module_name: None,
        lazuli_go_version: "v9.9.9".to_owned(),
        check: false,
    };
    let files = generate_v1(&module, &options);
    let go_mod = files
        .iter()
        .find(|f| f.path == "go.mod")
        .expect("go.mod missing");
    // Require names the Lazuli Go module (`lazuli.dev/runtime`); the
    // generated code imports the per-bucket subpackages
    // (`lazuli.dev/runtime/lazuli`, `lazuli.dev/runtime/lazuli/storage`,
    // ...) against it.
    assert!(go_mod.contents.contains("lazuli.dev/runtime v9.9.9"));
}

#[test]
fn cross_feature_user_defined_ref_emits_qualified_type_and_import() {
    // Phase Prep §1.1 — two features. `customer` declares
    // `Customer`; `org` declares `User`. A `Customer.owner: User`
    // field should emit `*org.User` plus a `lazuli/test-app/org`
    // import in `customer/resource.gen.go`. The analyzer leaves
    // `qname.feature = None` for these refs; codegen resolves them
    // via the cross-feature index.
    let mut module = minimal_module("test_app", "customer");
    module.features.push(empty_feature("org"));

    // Add Customer{owner: User} on `customer` feature.
    module.features[0].resources.push(Resource {
        name: "Customer".to_owned(),
        tenancy: None,
        soft_delete: false,
        timestamps: None,
        fields: vec![Field {
            name: "owner".to_owned(),
            type_ref: TypeRef::UserDefined(lazuli_ir::QualifiedName {
                feature: None,
                name: "User".to_owned(),
            }),
            required: true,
            unique: false,
            default: None,
            derived_from: None,
            previous_names: Vec::new(),
            span_ref: None,
        }],
        constraints: Vec::new(),
        validate: None,
        validates: Vec::new(),
        retention: None,
        previous_names: Vec::new(),
        span_ref: None,
    });

    // Add User on `org` feature.
    module.features[1].resources.push(Resource {
        name: "User".to_owned(),
        tenancy: None,
        soft_delete: false,
        timestamps: None,
        fields: vec![Field {
            name: "name".to_owned(),
            type_ref: TypeRef::Builtin(BuiltinType::Text),
            required: true,
            unique: false,
            default: None,
            derived_from: None,
            previous_names: Vec::new(),
            span_ref: None,
        }],
        constraints: Vec::new(),
        validate: None,
        validates: Vec::new(),
        retention: None,
        previous_names: Vec::new(),
        span_ref: None,
    });

    let files = generate_v1(&module, &GoEmitOptions::default());
    let customer_resource = files
        .iter()
        .find(|f| f.path == "customer/resource.gen.go")
        .expect("expected customer/resource.gen.go");

    assert!(
        customer_resource.contents.contains("Owner org.User"),
        "expected cross-feature `org.User` ref, got:\n{}",
        customer_resource.contents
    );
    assert!(
        customer_resource.contents.contains("\"lazuli/test-app/org\""),
        "expected cross-feature import path `lazuli/test-app/org`, got:\n{}",
        customer_resource.contents
    );

    // Sanity: the `org` feature's resource file still emits `User`
    // bare (same-package).
    let org_resource = files
        .iter()
        .find(|f| f.path == "org/resource.gen.go")
        .expect("expected org/resource.gen.go");
    assert!(
        org_resource.contents.contains("type User struct"),
        "expected `type User struct` in org/resource.gen.go, got:\n{}",
        org_resource.contents
    );
}

#[test]
fn command_kind_emits_typed_input_struct_and_command_value() {
    // Cell E3 integration smoke: a feature carrying one Command with
    // a typed input + Creates effect surfaces an extra
    // `<feature>/command.gen.go` alongside the resource file. The
    // shape mirrors `dist/go/customer/customer.gen.go:48-68` (proven
    // by the runtime spike). Per proposal §3.2 we land the typed
    // `<Verb><Resource>Input` struct plus the
    // `lazuli.Command[I, O]` value with `Effect: lazuli.Creates(...)`.
    let mut module = minimal_module("hostpoint", "customer");

    // Resource the command targets — same feature.
    module.features[0].resources.push(Resource {
        name: "Customer".to_owned(),
        tenancy: None,
        soft_delete: false,
        timestamps: None,
        fields: vec![
            Field {
                name: "name".to_owned(),
                type_ref: TypeRef::Builtin(BuiltinType::Text),
                required: true,
                unique: false,
                default: None,
                derived_from: None,
                previous_names: Vec::new(),
                span_ref: None,
            },
            Field {
                name: "email".to_owned(),
                type_ref: TypeRef::Builtin(BuiltinType::SemanticEmail),
                required: true,
                unique: false,
                default: None,
                derived_from: None,
                previous_names: Vec::new(),
                span_ref: None,
            },
        ],
        constraints: Vec::new(),
        validate: None,
        validates: Vec::new(),
        retention: None,
        previous_names: Vec::new(),
        span_ref: None,
    });

    // Command — `customer.create` with typed input + Creates effect.
    module.features[0].commands.push(Command {
        name: "create".to_owned(),
        kind: CommandKind::Create,
        route: Vec::new(),
        input: CommandInput::Typed(vec![
            TypedSlot {
                name: "name".to_owned(),
                type_ref: TypeRef::Builtin(BuiltinType::Text),
                required: true,
            },
            TypedSlot {
                name: "email".to_owned(),
                type_ref: TypeRef::Builtin(BuiltinType::SemanticEmail),
                required: true,
            },
        ]),
        target: None,
        lets: Vec::new(),
        effect: CommandEffect::Creates(CreateEffect {
            resource: QualifiedName {
                feature: None,
                name: "Customer".to_owned(),
            },
            from_input: false,
            assignments: vec![
                Assignment {
                    field: "name".to_owned(),
                    value: Expr::Path(Path::from_segments(["input", "name"])),
                },
                Assignment {
                    field: "email".to_owned(),
                    value: Expr::Path(Path::from_segments(["input", "email"])),
                },
            ],
        }),
        policy: PolicyRef::Atom("@role.admin".to_owned()),
        emits: vec!["customer_created".to_owned()],
        rate_limit: Some("30 per hour per ip".to_owned()),
        audit: None,
        approval: None,
        invalidates: Vec::new(),
        external_calls: Vec::new(),
        timeout: None,
        retry: None,
        idempotency: None,
        deprecated: None,
        tests: None,
        previous_names: Vec::new(),
        span_ref: None,
    });

    let files = generate_v1(&module, &GoEmitOptions::default());
    let command_file = files
        .iter()
        .find(|f| f.path == "customer/command.gen.go")
        .expect("expected customer/command.gen.go alongside the resource file");

    // Banner + package directive.
    assert!(
        command_file
            .contents
            .contains("// Code generated by lazuli; DO NOT EDIT."),
        "missing banner in command.gen.go:\n{}",
        command_file.contents
    );
    assert!(
        command_file.contents.contains("\npackage customer\n"),
        "expected `package customer` in command.gen.go:\n{}",
        command_file.contents
    );

    // Input struct shape — typed slots with JSON tags.
    assert!(
        command_file
            .contents
            .contains("type CreateCustomerInput struct {"),
        "expected `type CreateCustomerInput struct` in command.gen.go:\n{}",
        command_file.contents
    );
    assert!(
        command_file.contents.contains("Email lazuli.Email"),
        "expected `Email lazuli.Email` field row in CreateCustomerInput:\n{}",
        command_file.contents
    );

    // Command value shape — generic over input/output, with Creates effect.
    assert!(
        command_file
            .contents
            .contains("var createCustomer = lazuli.Command[CreateCustomerInput, Customer]{"),
        "expected `var createCustomer = lazuli.Command[CreateCustomerInput, Customer]` in command.gen.go:\n{}",
        command_file.contents
    );
    assert!(
        command_file
            .contents
            .contains("Effect: lazuli.Creates(&customerResource, lazuli.Bindings{"),
        "expected `Effect: lazuli.Creates(...)` block in command.gen.go:\n{}",
        command_file.contents
    );
    assert!(
        command_file
            .contents
            .contains("\"email\": lazuli.FromInput(\"email\"),"),
        "expected `email` binding row in command.gen.go:\n{}",
        command_file.contents
    );
    assert!(
        command_file
            .contents
            .contains("{Name: \"customer_created\", From: lazuli.FromExplicit},"),
        "expected emits row in command.gen.go:\n{}",
        command_file.contents
    );
    // Policy.Atom rendering — `@role.admin` splits into namespace/name.
    assert!(
        command_file
            .contents
            .contains("lazuli.PolicyAtom{{Namespace: \"role\", Name: \"admin\"}}"),
        "expected `PolicyAtom{{Namespace: \"role\", Name: \"admin\"}}` in command.gen.go:\n{}",
        command_file.contents
    );
}

#[test]
fn command_kind_skips_file_when_feature_declares_no_commands() {
    // Mirrors the resource / enum skip rule — a feature without
    // commands should not materialise `command.gen.go`.
    let module = minimal_module("hostpoint", "customer");
    let files = generate_v1(&module, &GoEmitOptions::default());
    assert!(
        files
            .iter()
            .all(|f| f.path != "customer/command.gen.go"),
        "expected no command.gen.go for an empty feature, got files: {:?}",
        files.iter().map(|f| &f.path).collect::<Vec<_>>()
    );
}
